tool_input.command:
$env:PYTHONIOENCODING='utf-8'
$f='分析产出\深市打新底仓专用标准.md'
Write-Output "== 章节结构 =="
Select-String -Path $f -Pattern '^#{1,3} ' | ForEach-Object {"$($_.LineNumber): $($_.Line)"}
Write-Output "== 含旧基准日/旧组合/旧数值的行 =="
Select-String -Path $f -Pattern '2026-10-15|2026-10-20|粤高速.*9.52|最终组合|衡接|沪市 5 只|深市 3 只全部' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(65,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== rebuild_sz_md.py 作用/输出 =="
Select-String -Path '分析产出\rebuild_sz_md.py' -Pattern 'read_csv|open\(|write|def |深市专用标准|OUT|MD' | Select-Object -First 25 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}

$env:PYTHONIOENCODING='utf-8'
$f='分析产出\清单拉取与卖出触发_操作手册.md'
Write-Output "== 章节 =="
Select-String -Path $f -Pattern '^#{1,3} ' | ForEach-Object {"$($_.LineNumber): $($_.Line)"}
Write-Output "== 过时引用(screen_all/统一11条/45%/宁波东阿电投/全市场统一) =="
Select-String -Path $f -Pattern 'screen_all|统一 11|全市场统一|45%|宁波银行|东阿|电投能源|screen_sz|深市专用|沪 11 条|7 条' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(60,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 全局残留扫描（过时表述） =="
foreach($f in (Get-ChildItem '分析产出' -Filter '*.md' -File).Name){
  $hits=Select-String -Path "分析产出\$f" -Pattern 'screen_all|全市场统一|统一 11 条框架|45%|2026-10-15 基准|宁波银行 18|东阿阿胶 13|电投能源 8'
  if($hits){ foreach($h in $hits){ "[$f] $($h.LineNumber): $($h.Line.Trim().Substring(0,[Math]::Min(55,$h.Line.Trim().Length)))" } }
}
Write-Output "（无输出=干净）"

$env:PYTHONIOENCODING='utf-8'
$root='D:\repository\数据湖\分析产出'; $arc="$root\归档_20261105\弃用的统一版"
New-Item -ItemType Directory -Force -Path $arc | Out-Null
foreach($f in '全市场_漏斗.csv','全市场_筛选结果.csv','全市场_逐条明细.csv','screen_all.py'){
  $src=Join-Path $root $f
  if(Test-Path -LiteralPath $src){ Move-Item -LiteralPath $src -Destination $arc -Force; "moved $f" }
}
"归档完成:"; Get-ChildItem $arc | Select-Object Length,Name

$env:PYTHONIOENCODING='utf-8';$env:PYTHONUTF8='1'
$env:HTTP_PROXY='http://127.0.0.1:7890'
python reselect_portfolio.py 2026-11-04 *> "$env:TEMP\r2.res" 2>&1; "reselect EXIT=$LASTEXITCODE"
Get-Content "$env:TEMP\r2.res" | Select-String -Pattern '合计|环保|银行|交运|单只最大' | ForEach-Object {$_.Line}
python final_portfolio_v3.py *> "$env:TEMP\v2.res" 2>&1; "v3 EXIT=$LASTEXITCODE"
Get-Content "$env:TEMP\v2.res" | Select-String -Pattern '校验：|FAIL' | ForEach-Object {$_.Line}

$env:PYTHONIOENCODING='utf-8'
$pats='深市替补席\.csv|final_portfolio_v2|screen_all.*现行'
foreach($f in (Get-ChildItem '分析产出' -Filter '*.md' -File).Name){
  $hits=Select-String -Path "分析产出\$f" -Pattern $pats
  if($hits){ foreach($h in $hits){ "[" + $f + " L" + $h.LineNumber + "] " + $h.Line.Trim().Substring(0,[Math]::Min(55,$h.Line.Trim().Length)) } }
}
Write-Output "（无输出=已清）"
Get-ChildItem '分析产出\归档_20261105\弃用的统一版' | Select-Object Name
